import path from 'path';
import {
  PREVIEW_ROUTE_LIMIT,
  previewRouteSchema,
} from '../types/preview-routes';

export const staticPreviewPagePath = ({
  entryPath,
  routePath,
}: {
  entryPath: string;
  routePath?: string;
}): string => {
  if (!routePath) return entryPath;
  const route = previewRouteSchema.parse(routePath);
  const pathname = decodeURIComponent(route.split(/[?#]/)[0]);
  if (pathname === '/') return entryPath;
  const relativePath = pathname.slice(1);
  return relativePath.endsWith('/')
    ? relativePath + 'index.html'
    : relativePath;
};

export const isStaticPreviewHtmlFile = ({
  assetPath,
  filePath,
  isEntry = false,
  previewRoutes,
}: {
  assetPath: string;
  filePath?: string;
  isEntry?: boolean;
  previewRoutes?: unknown;
}): boolean => {
  if (isEntry || /\.html?$/i.test(filePath ?? assetPath)) return true;
  if (
    !Array.isArray(previewRoutes) ||
    previewRoutes.length > PREVIEW_ROUTE_LIMIT
  )
    return false;
  return previewRoutes.some((route) => {
    const parsed = previewRouteSchema.safeParse(route);
    if (!parsed.success) return false;
    const pagePath = staticPreviewPagePath({
      entryPath: '',
      routePath: parsed.data,
    });
    return path.normalize(pagePath) === path.normalize(assetPath);
  });
};
